create type public.invoice_status as enum('waiting','issued','payment_pending','partial','paid');create type public.collection_status as enum('pending','partial','paid','overdue');create type public.collection_activity_type as enum('call','whatsapp','email','promise','partial_payment','completed','note');create type public.period_status as enum('open','review','closed');
create table public.service_periods(id uuid primary key default gen_random_uuid(),project_service_id uuid not null references public.project_services(id),client_id uuid not null references public.clients(id),project_id uuid not null references public.projects(id),service_id uuid not null references public.services(id),year integer not null check(year between 2000 and 2200),month integer not null check(month between 1 and 12),net_amount numeric(18,2)not null,vat_rate numeric(5,2)not null,vat_amount numeric(18,2)not null,gross_amount numeric(18,2)not null,currency public.currency_code not null,billing_preference public.billing_preference not null,invoice_status public.invoice_status not null default'waiting',collection_status public.collection_status not null default'pending',report_status public.report_status not null default'planned',cost_amount numeric(18,2)not null default 0,period_status public.period_status not null default'open',due_date date,notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),unique(project_service_id,year,month));
create table public.invoices(id uuid primary key default gen_random_uuid(),service_period_id uuid not null unique references public.service_periods(id),client_id uuid not null references public.clients(id),project_id uuid not null references public.projects(id),invoice_number text,invoice_date date,due_date date,net_amount numeric(18,2)not null,vat_amount numeric(18,2)not null,total_amount numeric(18,2)not null,currency public.currency_code not null,status public.invoice_status not null default'waiting',notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.receivables(id uuid primary key default gen_random_uuid(),service_period_id uuid not null unique references public.service_periods(id),client_id uuid not null references public.clients(id),project_id uuid not null references public.projects(id),total_amount numeric(18,2)not null,currency public.currency_code not null,due_date date,status public.collection_status not null default'pending',created_by uuid not null references public.profiles(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table public.payments(id uuid primary key default gen_random_uuid(),receivable_id uuid not null references public.receivables(id),amount numeric(18,2)not null check(amount>0),currency public.currency_code not null,payment_date date not null,account_id uuid,notes text,created_by uuid not null references public.profiles(id),created_at timestamptz not null default now());
create table public.collection_activities(id uuid primary key default gen_random_uuid(),receivable_id uuid not null references public.receivables(id),activity_type public.collection_activity_type not null,note text,promised_payment_date date,created_by uuid not null references public.profiles(id),activity_at timestamptz not null default now());
create index service_period_filter_idx on public.service_periods(year,month,collection_status);create index receivables_due_idx on public.receivables(status,due_date);create index payments_receivable_idx on public.payments(receivable_id,payment_date);create index collection_activities_idx on public.collection_activities(receivable_id,activity_at desc);create trigger set_updated_at before update on public.invoices for each row execute function public.set_updated_at();create trigger set_updated_at before update on public.receivables for each row execute function public.set_updated_at();
alter table public.service_periods enable row level security;alter table public.invoices enable row level security;alter table public.receivables enable row level security;alter table public.payments enable row level security;alter table public.collection_activities enable row level security;
insert into public.permissions(key,name,module)values('collections.read','Tahsilat verilerini görüntüle','collections'),('collections.manage','Tahsilat verilerini yönet','collections')on conflict(key)do nothing;
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where r.slug in('super-admin','partner','collections','accounting')and p.key='collections.read'on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where r.slug in('super-admin','partner','collections','accounting')and p.key='collections.manage'on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where r.slug='accounting'and p.key in('finance.read','finance.manage')on conflict do nothing;
insert into public.role_permissions(role_id,permission_id)select r.id,p.id from public.roles r cross join public.permissions p where r.slug in('collections','accounting')and p.key='projects.read_all'on conflict do nothing;
create policy periods_read on public.service_periods for select to authenticated using(public.has_permission('finance.read'));create policy periods_manage on public.service_periods for all to authenticated using(public.has_permission('finance.manage'))with check(public.has_permission('finance.manage'));
create policy invoices_access on public.invoices for all to authenticated using(public.has_permission('finance.read'))with check(public.has_permission('finance.manage'));create policy receivables_read on public.receivables for select to authenticated using(public.has_permission('finance.read')or public.has_permission('collections.read'));create policy receivables_manage on public.receivables for all to authenticated using(public.has_permission('finance.manage')or public.has_permission('collections.manage'))with check(public.has_permission('finance.manage')or public.has_permission('collections.manage'));create policy payments_read on public.payments for select to authenticated using(public.has_permission('finance.read')or public.has_permission('collections.read'));create policy payments_insert on public.payments for insert to authenticated with check((public.has_permission('finance.manage')or public.has_permission('collections.manage'))and created_by=auth.uid());create policy collection_activities_access on public.collection_activities for all to authenticated using(public.has_permission('finance.read')or public.has_permission('collections.read'))with check((public.has_permission('finance.manage')or public.has_permission('collections.manage'))and created_by=auth.uid());
create or replace function public.generate_service_periods(p_year integer,p_month integer)returns integer language plpgsql security invoker set search_path=''as $$declare ps record;price record;period_start date:=make_date(p_year,p_month,1);period_end date:=(make_date(p_year,p_month,1)+interval'1 month - 1 day')::date;new_period uuid;count_created integer:=0;begin if not public.has_permission('finance.manage')then raise exception'insufficient_permission'using errcode='42501';end if;for ps in select x.*,p.client_id from public.project_services x join public.projects p on p.id=x.project_id where x.status='active'and x.periodicity='monthly'and x.start_date<=period_end and(x.end_date is null or x.end_date>=period_start)loop select*into price from public.project_service_prices where project_service_id=ps.id and effective_from<=period_start and(effective_to is null or effective_to>=period_start)order by effective_from desc limit 1;if price.id is not null then insert into public.service_periods(project_service_id,client_id,project_id,service_id,year,month,net_amount,vat_rate,vat_amount,gross_amount,currency,billing_preference,due_date,created_by)values(ps.id,ps.client_id,ps.project_id,ps.service_id,p_year,p_month,price.net_price,price.vat_rate,round(price.net_price*price.vat_rate/100,2),round(price.net_price*(1+price.vat_rate/100),2),price.currency,ps.billing_preference,period_end+ps.payment_term_days,auth.uid())on conflict(project_service_id,year,month)do nothing returning id into new_period;if new_period is not null then insert into public.receivables(service_period_id,client_id,project_id,total_amount,currency,due_date,created_by)select id,client_id,project_id,gross_amount,currency,due_date,auth.uid()from public.service_periods where id=new_period;count_created:=count_created+1;new_period:=null;end if;end if;end loop;return count_created;end$$;
create or replace function public.record_receivable_payment(p_receivable_id uuid,p_amount numeric,p_payment_date date,p_notes text)returns uuid language plpgsql security invoker set search_path=''as $$declare rec public.receivables%rowtype;paid numeric;new_payment uuid;new_status public.collection_status;begin if not(public.has_permission('finance.manage')or public.has_permission('collections.manage'))then raise exception'insufficient_permission'using errcode='42501';end if;select*into rec from public.receivables where id=p_receivable_id for update;if not found then raise exception'receivable_not_found';end if;select coalesce(sum(amount),0)into paid from public.payments where receivable_id=p_receivable_id;if p_amount<=0 or paid+p_amount>rec.total_amount then raise exception'invalid_payment_amount';end if;insert into public.payments(receivable_id,amount,currency,payment_date,notes,created_by)values(p_receivable_id,p_amount,rec.currency,p_payment_date,p_notes,auth.uid())returning id into new_payment;paid:=paid+p_amount;new_status:=case when paid>=rec.total_amount then'paid'::public.collection_status else'partial'::public.collection_status end;update public.receivables set status=new_status where id=p_receivable_id;update public.service_periods set collection_status=new_status where id=rec.service_period_id;insert into public.collection_activities(receivable_id,activity_type,note,created_by)values(p_receivable_id,case when new_status='paid'then'completed'::public.collection_activity_type else'partial_payment'::public.collection_activity_type end,p_notes,auth.uid());return new_payment;end$$;
grant execute on function public.generate_service_periods(integer,integer)to authenticated;grant execute on function public.record_receivable_payment(uuid,numeric,date,text)to authenticated;
